=== FILE: tick_timer_cov_tb.sv ===
// Coverage-closing testbench for tick_timer.v (W = 16). It extends the idle
// testbench: it starts, stops, expires, reloads and clears the timer, toggles
// every wdata, load and count bit, and resets mid-run. Two kinds of checks:
// directed checks of the register map, and a cycle model compared with rdata
// and irq at every negedge. Stimulus changes at least 1 ns away from clock edges.
`timescale 1ns / 1ps
module tick_timer_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int dchecks = 0, derrors = 0;
    int mchecks = 0, merrors = 0;
    int guard = 0;
    logic chk_on = 1'b0;
    logic [8*64-1:0] nonce;

    // Reference model of the register behaviour.
    logic        m_en = 1'b0;
    logic        m_mode = 1'b0;
    logic        m_ie = 1'b0;
    logic        m_expired = 1'b0;
    logic [15:0] m_load = 16'd0;
    logic [15:0] m_count = 16'd0;
    wire m_wr_ctrl   = we && addr == 2'd0;
    wire m_wr_status = we && addr == 2'd3;
    wire m_expire    = m_en && m_count == 16'd0 && !m_wr_ctrl;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    always @(posedge clk) begin
        if (!rst_n) begin
            m_en      <= 1'b0;
            m_mode    <= 1'b0;
            m_ie      <= 1'b0;
            m_load    <= 16'd0;
            m_count   <= 16'd0;
            m_expired <= 1'b0;
        end else begin
            m_expired <= m_expire | (m_expired & ~(m_wr_status & wdata[0]));
            if (we && addr == 2'd1)
                m_load <= wdata[15:0];
            if (m_wr_ctrl) begin
                m_en   <= wdata[0];
                m_mode <= wdata[1];
                m_ie   <= wdata[2];
                if (wdata[0] && !m_en)
                    m_count <= m_load;
            end else if (m_en) begin
                if (m_count != 16'd0)
                    m_count <= m_count - 16'd1;
                else if (m_mode)
                    m_count <= m_load;
                else
                    m_en <= 1'b0;
            end
        end
    end

    function automatic logic [31:0] m_read(input logic [1:0] a);
        case (a)
            2'd0:    m_read = {29'd0, m_ie, m_mode, m_en};
            2'd1:    m_read = {16'd0, m_load};
            2'd2:    m_read = {16'd0, m_count};
            default: m_read = {31'd0, m_expired};
        endcase
    endfunction

    // Every-cycle comparison against the model, midway between edges.
    always @(negedge clk) begin
        if (chk_on) begin
            mchecks++;
            if (rdata !== m_read(addr) || irq !== (m_expired & m_ie)) merrors++;
        end
    end

    task automatic next_cycle;
        @(posedge clk);
        #1;
    endtask

    task automatic dcheck(input logic cond);
        dchecks++;
        if (cond !== 1'b1) derrors++;
    endtask

    task automatic peek(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        dchecks++;
        if (rdata !== expected) derrors++;
    endtask

    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    initial begin
        // Reset, then release 1 ns after an edge.
        repeat (3) @(posedge clk);
        #1 rst_n = 1'b1;
        chk_on = 1'b1;
        next_cycle;
        peek(2'd0, 32'd0); peek(2'd1, 32'd0); peek(2'd2, 32'd0);
        next_cycle;
        peek(2'd3, 32'd0); dcheck(irq === 1'b0);

        // LOAD stores W bits; upper wdata bits are ignored and read as zero.
        write(2'd1, 32'hFFFF_FFFF); peek(2'd1, 32'h0000_FFFF);
        write(2'd1, 32'h0000_0000); peek(2'd1, 32'h0000_0000);
        write(2'd1, 32'hA5A5_5A5A); peek(2'd1, 32'h0000_5A5A);

        // Start from all ones, decrement, stop (count frozen), restart from zero.
        write(2'd1, 32'h0000_FFFF);
        write(2'd0, 32'h0000_0001); peek(2'd2, 32'h0000_FFFF); peek(2'd0, 32'h0000_0001);
        next_cycle;                 peek(2'd2, 32'h0000_FFFE);
        write(2'd0, 32'h0000_0000); peek(2'd2, 32'h0000_FFFE); peek(2'd0, 32'h0000_0000);
        next_cycle;                 peek(2'd2, 32'h0000_FFFE);
        write(2'd1, 32'h0000_0000); peek(2'd1, 32'h0000_0000);
        write(2'd0, 32'h0000_0001); peek(2'd2, 32'h0000_0000); peek(2'd0, 32'h0000_0001); peek(2'd3, 32'd0);
        // One-shot expiry: EXPIRED set, EN cleared, no irq without IE.
        next_cycle;                 peek(2'd3, 32'd1); peek(2'd0, 32'd0); peek(2'd2, 32'd0);
        dcheck(irq === 1'b0);

        // STATUS is write-one-to-clear on bit 0 only.
        write(2'd3, 32'hFFFF_FFFE); peek(2'd3, 32'd1);
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd0);

        // IE without EN does not start; one-shot with IE raises irq.
        write(2'd0, 32'h0000_0004); peek(2'd0, 32'h0000_0004); dcheck(irq === 1'b0);
        write(2'd1, 32'h0000_0003);
        write(2'd0, 32'h0000_0005); peek(2'd2, 32'd3); peek(2'd0, 32'h0000_0005);
        next_cycle; peek(2'd2, 32'd2);
        next_cycle; peek(2'd2, 32'd1);
        next_cycle; peek(2'd2, 32'd0); peek(2'd3, 32'd0);
        next_cycle; peek(2'd3, 32'd1); peek(2'd0, 32'h0000_0004); dcheck(irq === 1'b1);
        next_cycle; peek(2'd3, 32'd1); dcheck(irq === 1'b1);
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd0); dcheck(irq === 1'b0);

        // Periodic mode: reload on expiry, EN stays set.
        write(2'd1, 32'h0000_0002);
        write(2'd0, 32'h0000_0007); peek(2'd2, 32'd2); peek(2'd0, 32'h0000_0007);
        next_cycle; peek(2'd2, 32'd1);
        next_cycle; peek(2'd2, 32'd0); peek(2'd3, 32'd0);
        next_cycle; peek(2'd2, 32'd2); peek(2'd3, 32'd1); peek(2'd0, 32'h0000_0007);
        dcheck(irq === 1'b1);
        // A clear away from an expiry clears.
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd0); peek(2'd2, 32'd1); dcheck(irq === 1'b0);
        next_cycle; peek(2'd2, 32'd0); peek(2'd3, 32'd0);
        // An expiry wins over a clear at the same edge.
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd1); peek(2'd2, 32'd2);
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd0); peek(2'd2, 32'd1);
        write(2'd1, 32'h0000_0009); peek(2'd2, 32'd0); peek(2'd1, 32'd9);
        // A CTRL write takes the expiring edge's place: no expiry, no reload.
        write(2'd0, 32'h0000_0007); peek(2'd2, 32'd0); peek(2'd3, 32'd0); peek(2'd0, 32'h0000_0007);
        next_cycle; peek(2'd2, 32'd9); peek(2'd3, 32'd1);
        // Rewriting CTRL while running neither restarts nor decrements.
        write(2'd0, 32'h0000_0007); peek(2'd2, 32'd9);
        next_cycle; peek(2'd2, 32'd8);
        // Switch to one-shot while running; run to the end.
        write(2'd0, 32'h0000_0005); peek(2'd0, 32'h0000_0005); peek(2'd2, 32'd8);
        guard = 0;
        while (m_en && guard < 64) begin
            next_cycle;
            guard++;
        end
        dcheck(guard < 64);
        peek(2'd0, 32'h0000_0004); peek(2'd2, 32'd0); peek(2'd3, 32'd1);
        dcheck(irq === 1'b1);

        // Clear, then start with every wdata bit set (upper bits ignored).
        write(2'd3, 32'h0000_0001); peek(2'd3, 32'd0);
        write(2'd0, 32'hFFFF_FFFF); peek(2'd0, 32'h0000_0007); peek(2'd2, 32'd9);
        next_cycle; peek(2'd2, 32'd8);

        // Reset in the middle of a run returns every register to zero.
        rst_n = 1'b0;
        next_cycle;
        next_cycle;
        peek(2'd0, 32'd0); peek(2'd2, 32'd0);
        rst_n = 1'b1;
        next_cycle;
        peek(2'd1, 32'd0); peek(2'd3, 32'd0); dcheck(irq === 1'b0);
        next_cycle;

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (dchecks - derrors) + (mchecks - merrors), derrors + merrors);
        $finish;
    end
endmodule
=== END FILE ===
